 export const SECURITY_ANOMALY_EVENT_TYPES = [
   "challenge_replayed",
   "wrong_session_challenge",
   "malformed_challenge",
 ] as const;
 
 export const RATE_LIMIT_EVENT_TYPES = [
   "challenge_expired_use",
   "challenge_replayed",
